(* [comment removed for export] *)
Lemma mcs_byte_blks : forall C A m md E log (rb : expr) (s F p k : Z) (blks : list (expr * Z * Z)) (x : word),
  Cok C -> W C A m md -> (c_top C - LSTK <= s - F)%Z -> log_flat E log ->
  ex_in_regions ((rb, (- F)%Z, 0%Z) :: map exW_blk_region blks) log = true -> edenot E rb = Z_to_bv 64 s -> (0 <= s < 2 ^ 64)%Z ->
  mcs_blks_ok A E p blks -> live A (Z_to_bv 64 p) = Some k -> (0 <= p)%Z -> (p + k < 2 ^ 64)%Z -> (0 < k)%Z ->
  (p <= u x < p + k)%Z -> mem_denot E m log x = m x.
Proof.
