Definition MEMSET_PC : Z := 0x11e6d4.
Lemma mcs_memset_hop : forall C A (Ar : AS) M md regs (s d n : Z) (ret : word) (S : TSet),
  Cok C -> W C A M md -> sub_live Ar A -> (s <= c_top C)%Z ->
  (c_top C - LSTK <= d)%Z -> (1 <= n)%Z -> (d + n <= s)%Z ->
  getr regs 1 = ret -> ret_ok ret -> getr regs 10 = Z_to_bv 64 d -> getr regs 11 = Z_to_bv 64 0 -> getr regs 12 = Z_to_bv 64 n ->
  (forall regs' m', W C A m' md -> POSTM C Ar s M m' -> getr regs' 10 = Z_to_bv 64 d ->
      regs_agree (fun r => In r memset_clob) regs regs' ->
      (forall x : word, ~ (d <= u x < d + n)%Z -> m' x = M x) ->
      (forall i, (0 <= i < n)%Z -> m' (Z_to_bv 64 (d + i)) = Some (Z_to_bv 8 0)) ->
      realizes SEGS (mkCfg (mkst regs' ret m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst regs (Z_to_bv 64 MEMSET_PC) M al_rom) md) S.
Proof.
  intros C A Ar M md regs s d n ret S CK HW SUB Hs Hd Hn Hdn H1 Hret H10 H11 H12 K.
  pose proof CK as [T1 T2 T3 T4 T5]. laypins. cbn [fst snd ll_img ll_ro LLU16] in *. pose proof LSTK_val as LV.
  pose proof (u64_range (c_sp0 C)) as RSP.
  unfold MEMSET_PC. replace (Z_to_bv 64 0x11e6d4) with (0x11e6d4 : word) by (apply bv_eq; reflexivity).
  apply (memset_at md regs M al_rom d n ret S (w_pure _ _ _ _ HW)); try lia; try assumption.
  - apply (W_sok_win C A M md d (Z.to_nat n) CK HW); [lia | rewrite Z2Nat.id by lia; lia].
  - intros regs' R10 RA. destruct (memset_post_mem M d n ltac:(lia) ltac:(lia)) as [ZIN [ZOUT ZG]].
    apply K; try assumption.
    + apply (W_local C A M md _ (d + n) CK HW ltac:(lia)); [| exact ZG].
      intros a NE. left. unfold scratch.
      destruct (Z_lt_le_dec (u a) d) as [L1 | L1]; [exfalso; apply NE; apply ZOUT; lia |].
      destruct (Z_lt_le_dec (u a) (d + n)) as [L2 | L2]; [lia | exfalso; apply NE; apply ZOUT; lia].
    + apply (POSTM_sub C Ar A s M _ SUB). apply (POSTM_range C A M md _ d (d + n) s CK HW); [| lia | lia | lia].
      intros a NA. apply ZOUT. lia.
    + intros x NX. apply ZOUT. lia.
Qed.

